/* ---- list [рац] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_Lr { dan_hdr h; int64_t len, cap; dan_rat *items; };

static void dl_Lr_destroy(dan_hdr *h) {
    dl_Lr *l = (dl_Lr *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) DAN_NOREL(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_Lr *dl_Lr_from(int64_t n, dan_rat const *src) {
    dl_Lr *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_Lr_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dan_rat));
    for (int64_t i = 0; i < n; i++) l->items[i] = DAN_ID(src[i]);
    return l;
}

static void dl_Lr_push(dl_Lr *l, dan_rat v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dan_rat));
    }
    l->items[l->len++] = DAN_ID(v);
}

static dan_rat dl_Lr_get(const dl_Lr *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dan_rat *dl_Lr_at(dl_Lr *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_Lr_set(dl_Lr *l, int64_t i, dan_rat v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dan_rat old = l->items[i];
    l->items[i] = DAN_ID(v);
    DAN_NOREL(old);
    (void)old;
}

static void dl_Lr_write(const dl_Lr *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dan_write_rat(l->items[i]);
    }
    putchar(']');
}

static void dl_Lr_insert(dl_Lr *l, int64_t i, dan_rat v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_Lr_push(l, v);
    dan_rat last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dan_rat));
    l->items[i] = last;
}

static void dl_Lr_remove(dl_Lr *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dan_rat old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dan_rat));
    l->len--;
    DAN_NOREL(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_Lr *dl_Lr_copy(const dl_Lr *l) {
    return dl_Lr_from(l->len, l->items);
}

static inline dl_Lr *dl_Lr_share(dl_Lr *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_Lr_release(dl_Lr *l) { if (l) dan_hdr_release(&l->h, dl_Lr_destroy); }
static inline void dl_Lr_give(dl_Lr *l) { if (l) dan_hdr_give(&l->h, dl_Lr_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_Lr *dl_Lr_mut(dl_Lr **pp) {
    dl_Lr *l = *pp;
    if (l->h.rc > 1) {
        dl_Lr *r = dl_Lr_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_Lr *dl_Lr_reversed(const dl_Lr *l) {
    dl_Lr *r = dl_Lr_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dan_rat t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_Lr *dl_Lr_slice(const dl_Lr *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_Lr_from(b - a + 1, l->items + a);
}

static dan_str dl_Lr_str(const dl_Lr *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dan_rat_to_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_Lr_find(const dl_Lr *l, dan_rat b) {
    for (int64_t i = 0; i < l->len; i++) { dan_rat a = l->items[i]; if ((dan_rat_cmp(a, b) == 0)) return i; }
    return -1;
}
static bool dl_Lr_contains(const dl_Lr *l, dan_rat b) { return dl_Lr_find(l, b) >= 0; }
static bool dl_Lr_eq(const dl_Lr *x, const dl_Lr *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dan_rat a = x->items[i]; dan_rat b = y->items[i]; if (!((dan_rat_cmp(a, b) == 0))) return false; }
    return true;
}


