static inline void dl_Lp_release(dl_Lp *l) { if (l) dan_hdr_release(&l->h, dl_Lp_destroy); }
static inline void dl_Lp_give(dl_Lp *l) { if (l) dan_hdr_give(&l->h, dl_Lp_destroy); }

