static inline dl_LTPravka *dl_LTPravka_share(dl_LTPravka *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LTPravka_release(dl_LTPravka *l) { if (l) dan_hdr_release(&l->h, dl_LTPravka_destroy); }
static inline void dl_LTPravka_give(dl_LTPravka *l) { if (l) dan_hdr_give(&l->h, dl_LTPravka_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LTPravka *dl_LTPravka_mut(dl_LTPravka **pp) {
    dl_LTPravka *l = *pp;
    if (l->h.rc > 1) {
        dl_LTPravka *r = dl_LTPravka_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LTPravka *dl_LTPravka_reversed(const dl_LTPravka *l) {
    dl_LTPravka *r = dl_LTPravka_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dt_Pravka t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LTPravka *dl_LTPravka_slice(const dl_LTPravka *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LTPravka_from(b - a + 1, l->items + a);
}

static dan_str dl_LTPravka_str(const dl_LTPravka *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dt_Pravka_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LTPravka_find(const dl_LTPravka *l, dt_Pravka b) {
    for (int64_t i = 0; i < l->len; i++) { dt_Pravka a = l->items[i]; if (dt_Pravka_eq(a, b)) return i; }
    return -1;
}
static bool dl_LTPravka_contains(const dl_LTPravka *l, dt_Pravka b) { return dl_LTPravka_find(l, b) >= 0; }
static bool dl_LTPravka_eq(const dl_LTPravka *x, const dl_LTPravka *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dt_Pravka a = x->items[i]; dt_Pravka b = y->items[i]; if (!(dt_Pravka_eq(a, b))) return false; }
    return true;
}


/* ---- list [[цел]] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_LLi { dan_hdr h; int64_t len, cap; dl_Li* *items; };

static void dl_LLi_destroy(dan_hdr *h) {
    dl_LLi *l = (dl_LLi *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dl_Li_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_LLi *dl_LLi_from(int64_t n, dl_Li* const *src) {
    dl_LLi *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_LLi_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dl_Li*));
    for (int64_t i = 0; i < n; i++) l->items[i] = dl_Li_share(src[i]);
    return l;
}

static void dl_LLi_push(dl_LLi *l, dl_Li* v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dl_Li*));
    }
    l->items[l->len++] = dl_Li_share(v);
}

static dl_Li* dl_LLi_get(const dl_LLi *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dl_Li* *dl_LLi_at(dl_LLi *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_LLi_set(dl_LLi *l, int64_t i, dl_Li* v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dl_Li* old = l->items[i];
    l->items[i] = dl_Li_share(v);
    dl_Li_release(old);
    (void)old;
}

static void dl_LLi_write(const dl_LLi *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dl_Li_write(l->items[i]);
    }
    putchar(']');
}

static void dl_LLi_insert(dl_LLi *l, int64_t i, dl_Li* v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_LLi_push(l, v);
    dl_Li* last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dl_Li*));
    l->items[i] = last;
}

static void dl_LLi_remove(dl_LLi *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dl_Li* old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dl_Li*));
    l->len--;
    dl_Li_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_LLi *dl_LLi_copy(const dl_LLi *l) {
    return dl_LLi_from(l->len, l->items);
}

static inline dl_LLi *dl_LLi_share(dl_LLi *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LLi_release(dl_LLi *l) { if (l) dan_hdr_release(&l->h, dl_LLi_destroy); }
static inline void dl_LLi_give(dl_LLi *l) { if (l) dan_hdr_give(&l->h, dl_LLi_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LLi *dl_LLi_mut(dl_LLi **pp) {
    dl_LLi *l = *pp;
    if (l->h.rc > 1) {
        dl_LLi *r = dl_LLi_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LLi *dl_LLi_reversed(const dl_LLi *l) {
    dl_LLi *r = dl_LLi_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dl_Li* t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LLi *dl_LLi_slice(const dl_LLi *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LLi_from(b - a + 1, l->items + a);
}

static dan_str dl_LLi_str(const dl_LLi *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dl_Li_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LLi_find(const dl_LLi *l, dl_Li* b) {
    for (int64_t i = 0; i < l->len; i++) { dl_Li* a = l->items[i]; if (dl_Li_eq(a, b)) return i; }
    return -1;
}
static bool dl_LLi_contains(const dl_LLi *l, dl_Li* b) { return dl_LLi_find(l, b) >= 0; }
static bool dl_LLi_eq(const dl_LLi *x, const dl_LLi *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dl_Li* a = x->items[i]; dl_Li* b = y->items[i]; if (!(dl_Li_eq(a, b))) return false; }
    return true;
}


/* ---- dictionaries: hashing ---- */
static uint64_t dan_hash_i(int64_t v) {
    uint64_t z = (uint64_t)v + 0x9E3779B97F4A7C15ULL;
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return z ^ (z >> 31);
}
static uint64_t dan_hash_s(dan_str s) {
    uint64_t h = 0xCBF29CE484222325ULL;
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) { h ^= *p; h *= 0x100000001B3ULL; }
    return dan_hash_i((int64_t)h);
}
static uint64_t dan_hash_r(dan_rat r) { return dan_hash_i(r.n) * 31 + dan_hash_i(r.d); }
static void dan_key_error(dan_str key, int line) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, DAN_MSG_NO_KEY);
    dan_buf_add(&b, key);
    dan_error(b.s, line);
}


/* ---- dictionary {стр: [стр]} ---- */
struct dm_DsLs { dan_hdr h; int64_t len, n, cap, slots; dan_str *keys; dl_Ls* *vals; uint64_t *hashes; bool *alive; int64_t *index; };

static void dm_DsLs_destroy(dan_hdr *h) {
    dm_DsLs *d = (dm_DsLs *)(void *)h;
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) { dan_str_release(d->keys[e]); dl_Ls_release(d->vals[e]); }
    dan_free(d->hashes);
    dan_free(d);
}
static dm_DsLs *dm_DsLs_new(void) {
    dm_DsLs *d = dan_alloc(sizeof *d);
    dan_hdr_new(&d->h, dm_DsLs_destroy);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsLs *dm_DsLs_new_detached(void) {
    dm_DsLs *d = dan_alloc(sizeof *d);
    dan_hdr_detached(&d->h);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsLs *dm_DsLs_share(dm_DsLs *d) { if (d) dan_hdr_share(&d->h); return d; }
static void dm_DsLs_release(dm_DsLs *d) { if (d) dan_hdr_release(&d->h, dm_DsLs_destroy); }
static void dm_DsLs_give(dm_DsLs *d) { if (d) dan_hdr_give(&d->h, dm_DsLs_destroy); }

/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_DsLs_block(dm_DsLs *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(dan_str) * c + 7) & ~(size_t)7, vb = (sizeof(dl_Ls*) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (dl_Ls* *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_DsLs_reindex(dm_DsLs *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_DsLs_lookup(const dm_DsLs *d, dan_str k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { dan_str a = d->keys[e], b = k; if (dan_str_eq(a, b)) return e; }
    }
}
static void dm_DsLs_grow(dm_DsLs *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dan_str *keys = d->keys; dl_Ls* *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_DsLs_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_DsLs_reindex(d);
}
static void dm_DsLs_put(dm_DsLs *d, dan_str k, dl_Ls* v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsLs_lookup(d, k, h);
    if (e >= 0) { dl_Ls* old = d->vals[e]; d->vals[e] = dl_Ls_share(v); dl_Ls_release(old); (void)old; return; }
    if (d->n == d->cap) dm_DsLs_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dl_Ls_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* запись в новый словарь значений, которые уже учтены (копия для задачи) */
static void dm_DsLs_put_raw(dm_DsLs *d, dan_str k, dl_Ls* v) {
    uint64_t h = dan_hash_s(k);
    if (d->n == d->cap) dm_DsLs_grow(d);
    int64_t e = d->n++;
    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* место значения по ключу; если ключа нет, запись создаётся со значением v (одно обращение
   вместо получить и записать) */
static dl_Ls* *dm_DsLs_slot(dm_DsLs *d, dan_str k, dl_Ls* v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsLs_lookup(d, k, h);
    if (e < 0) {
        if (d->n == d->cap) dm_DsLs_grow(d);
        e = d->n++;
        d->keys[e] = dan_str_share(k); d->vals[e] = dl_Ls_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
        d->index[p] = e;
    }
    return &d->vals[e];
}
static dm_DsLs *dm_DsLs_from(int64_t n, const dan_str *ks, const dl_Ls* *vs) {
    dm_DsLs *d = dm_DsLs_new();
    for (int64_t i = 0; i < n; i++) dm_DsLs_put(d, ks[i], vs[i]);
    return d;
}
static dl_Ls* dm_DsLs_get(const dm_DsLs *d, dan_str k, int line) {
    int64_t e = dm_DsLs_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return d->vals[e];
}
static dl_Ls* *dm_DsLs_at(dm_DsLs *d, dan_str k, int line) {
    int64_t e = dm_DsLs_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return &d->vals[e];
}
static bool dm_DsLs_contains(const dm_DsLs *d, dan_str k) { return dm_DsLs_lookup(d, k, dan_hash_s(k)) >= 0; }

static do_Ls dm_DsLs_find(const dm_DsLs *d, dan_str k) {
    int64_t e = dm_DsLs_lookup(d, k, dan_hash_s(k));
    return e < 0 ? do_Ls_none() : do_Ls_some(d->vals[e]);
}
static dl_Ls* dm_DsLs_get_or(const dm_DsLs *d, dan_str k, dl_Ls* v) {
    int64_t e = dm_DsLs_lookup(d, k, dan_hash_s(k));
    return e < 0 ? v : d->vals[e];
}
static void dm_DsLs_remove(dm_DsLs *d, dan_str k) {
    int64_t e = dm_DsLs_lookup(d, k, dan_hash_s(k));
    if (e >= 0) { d->alive[e] = false; d->len--; dan_str_release(d->keys[e]); dl_Ls_release(d->vals[e]); }
}
static dl_Ls *dm_DsLs_keys(const dm_DsLs *d) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Ls_push(r, d->keys[e]);
    return r;
}
static dl_LLs *dm_DsLs_values(const dm_DsLs *d) {
    dl_LLs *r = dl_LLs_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_LLs_push(r, d->vals[e]);
    return r;
}
/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_DsLs *dm_DsLs_copy(const dm_DsLs *d) {
    dm_DsLs *r = dm_DsLs_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_DsLs_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dl_Ls_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_DsLs_reindex(r);
    return r;
}
static dm_DsLs *dm_DsLs_mut(dm_DsLs **pp) {
    dm_DsLs *d = *pp;
    if (d->h.rc > 1) { dm_DsLs *r = dm_DsLs_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_DsLs_str(const dm_DsLs *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dl_Ls_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_DsLs_write(const dm_DsLs *d) { fputs(dm_DsLs_str(d), stdout); }


static bool dm_DsLs_eq(const dm_DsLs *x, const dm_DsLs *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsLs_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dl_Ls* a = x->vals[e]; dl_Ls* b = y->vals[f];
        if (!(dl_Ls_eq(a, b))) return false;
    }
    return true;
}


/* ---- dictionary {стр: стр} ---- */
struct dm_Dss { dan_hdr h; int64_t len, n, cap, slots; dan_str *keys; dan_str *vals; uint64_t *hashes; bool *alive; int64_t *index; };

static void dm_Dss_destroy(dan_hdr *h) {
    dm_Dss *d = (dm_Dss *)(void *)h;
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) { dan_str_release(d->keys[e]); dan_str_release(d->vals[e]); }
    dan_free(d->hashes);
    dan_free(d);
}
static dm_Dss *dm_Dss_new(void) {
    dm_Dss *d = dan_alloc(sizeof *d);
    dan_hdr_new(&d->h, dm_Dss_destroy);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_Dss *dm_Dss_new_detached(void) {
    dm_Dss *d = dan_alloc(sizeof *d);
    dan_hdr_detached(&d->h);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_Dss *dm_Dss_share(dm_Dss *d) { if (d) dan_hdr_share(&d->h); return d; }
static void dm_Dss_release(dm_Dss *d) { if (d) dan_hdr_release(&d->h, dm_Dss_destroy); }
static void dm_Dss_give(dm_Dss *d) { if (d) dan_hdr_give(&d->h, dm_Dss_destroy); }

/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_Dss_block(dm_Dss *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(dan_str) * c + 7) & ~(size_t)7, vb = (sizeof(dan_str) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_Dss_reindex(dm_Dss *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_Dss_lookup(const dm_Dss *d, dan_str k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { dan_str a = d->keys[e], b = k; if (dan_str_eq(a, b)) return e; }
    }
}
static void dm_Dss_grow(dm_Dss *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dan_str *keys = d->keys; dan_str *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_Dss_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_Dss_reindex(d);
}
static void dm_Dss_put(dm_Dss *d, dan_str k, dan_str v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_Dss_lookup(d, k, h);
    if (e >= 0) { dan_str old = d->vals[e]; d->vals[e] = dan_str_share(v); dan_str_release(old); (void)old; return; }
    if (d->n == d->cap) dm_Dss_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dan_str_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* запись в новый словарь значений, которые уже учтены (копия для задачи) */
static void dm_Dss_put_raw(dm_Dss *d, dan_str k, dan_str v) {
    uint64_t h = dan_hash_s(k);
    if (d->n == d->cap) dm_Dss_grow(d);
    int64_t e = d->n++;
    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* место значения по ключу; если ключа нет, запись создаётся со значением v (одно обращение
   вместо получить и записать) */
static dan_str *dm_Dss_slot(dm_Dss *d, dan_str k, dan_str v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_Dss_lookup(d, k, h);
    if (e < 0) {
        if (d->n == d->cap) dm_Dss_grow(d);
        e = d->n++;
        d->keys[e] = dan_str_share(k); d->vals[e] = dan_str_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
        d->index[p] = e;
    }
    return &d->vals[e];
}
static dm_Dss *dm_Dss_from(int64_t n, const dan_str *ks, const dan_str *vs) {
    dm_Dss *d = dm_Dss_new();
    for (int64_t i = 0; i < n; i++) dm_Dss_put(d, ks[i], vs[i]);
    return d;
}
static dan_str dm_Dss_get(const dm_Dss *d, dan_str k, int line) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return d->vals[e];
}
static dan_str *dm_Dss_at(dm_Dss *d, dan_str k, int line) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return &d->vals[e];
}
static bool dm_Dss_contains(const dm_Dss *d, dan_str k) { return dm_Dss_lookup(d, k, dan_hash_s(k)) >= 0; }

static do_s dm_Dss_find(const dm_Dss *d, dan_str k) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    return e < 0 ? do_s_none() : do_s_some(d->vals[e]);
}
static dan_str dm_Dss_get_or(const dm_Dss *d, dan_str k, dan_str v) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    return e < 0 ? v : d->vals[e];
}
static void dm_Dss_remove(dm_Dss *d, dan_str k) {
    int64_t e = dm_Dss_lookup(d, k, dan_hash_s(k));
    if (e >= 0) { d->alive[e] = false; d->len--; dan_str_release(d->keys[e]); dan_str_release(d->vals[e]); }
}
static dl_Ls *dm_Dss_keys(const dm_Dss *d) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Ls_push(r, d->keys[e]);
    return r;
}
static dl_Ls *dm_Dss_values(const dm_Dss *d) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Ls_push(r, d->vals[e]);
    return r;
}
/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_Dss *dm_Dss_copy(const dm_Dss *d) {
    dm_Dss *r = dm_Dss_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_Dss_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dan_str_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_Dss_reindex(r);
    return r;
}
static dm_Dss *dm_Dss_mut(dm_Dss **pp) {
    dm_Dss *d = *pp;
    if (d->h.rc > 1) { dm_Dss *r = dm_Dss_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_Dss_str(const dm_Dss *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dan_quote_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_Dss_write(const dm_Dss *d) { fputs(dm_Dss_str(d), stdout); }


static bool dm_Dss_eq(const dm_Dss *x, const dm_Dss *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_Dss_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dan_str a = x->vals[e]; dan_str b = y->vals[f];
        if (!(dan_str_eq(a, b))) return false;
    }
    return true;
}


