    if (d->n == d->cap) dm_DsTproverkau2eSoobshhenie_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dt_proverkau2eSoobshhenie_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
